WF.theme=function(){const CSS_VARS=Object.keys(WF.THEME_DEFAULTS);function sanitizeColors(rawColors){const safe={};return rawColors&&"object"==typeof rawColors?(CSS_VARS.forEach((cssVar=>{const value=rawColors[cssVar];"string"==typeof value&&WF.HEX_COLOR.test(value)&&(safe[cssVar]=value)})),safe):safe}function apply(colors){const safeColors=sanitizeColors(colors);CSS_VARS.forEach((cssVar=>document.documentElement.style.setProperty(cssVar,safeColors[cssVar]||WF.THEME_DEFAULTS[cssVar])))}return{CSS_VARS:CSS_VARS,apply:apply,init:function(){apply(WF.options.load().themeColors||{})},setColor:function(cssVar,hexValue){if(!CSS_VARS.includes(cssVar)||!HEX_COLOR.test(hexValue))return;const options=WF.options.load(),themeColors={...options.themeColors||{},[cssVar]:hexValue};WF.options.save({...options,themeColors:themeColors}),apply(themeColors)},reset:function(){WF.options.save({...WF.options.load(),themeColors:{}}),apply({})},getColor:function(cssVar){return sanitizeColors(WF.options.load().themeColors)[cssVar]||WF.THEME_DEFAULTS[cssVar]},sanitizeColors:sanitizeColors}}();